def make_meetings():
    for name, (mid, start, saved, when, sections) in MEETINGS.items():
        doc = {"formatVersion": "1.0", "meetingId": mid, "meetingStartAt": start, "savedAt": saved,
               "header": f"{HEADER}\n{when}", "footer": FOOTER,
               "sections": [{"title": t, "content": c} for t, c in sections]}
        (HERE / name).write_text(json.dumps(doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def make_requirements(font, path):
    pdf = Report(font)
    pdf.add_page()
    draw = {"title": lambda t: (pdf.set_font("noto", size=16), pdf.multi_cell(0, 10, t, new_x="LMARGIN", new_y="NEXT"),
                                pdf.set_font("noto", size=11)),
            "h1": lambda t: (pdf.ln(3), pdf.heading(t)), "h2": pdf.subheading, "p": pdf.para, "list": pdf.bullets}
    for kind, *args in REQUIREMENTS:
        if kind == "table":
            pdf.grid(*args)
        else:
            draw[kind](*args)
    pdf.output(str(path))


def make_schedule_budget(path):
    wb = Workbook()
    wb.remove(wb.active)
    for name, rows in SHEETS.items():
        ws = wb.create_sheet(name)
        for row in rows:
            ws.append(list(row))
    wb.save(str(path))


def main():
    font = Path(sys.argv[1]) if len(sys.argv) > 1 else next((p for p in FONT_CANDIDATES if p.exists()), None)
    if font is None:
        sys.exit("한글 글꼴이 없음. 글꼴 파일 경로를 인자로 준다 (make_upload_samples.py 와 같음)")
    make_meetings()
    make_requirements(font, HERE / "requirements.pdf")
    make_schedule_budget(HERE / "schedule_budget.xlsx")
    print(f"만듦: {HERE}")


if __name__ == "__main__":
    main()
